argets\\\"][f\\\"rd_{dlt:.2f}\\\"] = {\\\"n_pairs_closed_form\\\": ncf,\\n                                          \\\"episodes_two_arms\\\": None if not ncf else 2 * ncf,\\n                                          \\\"exact_power_at_that_n\\\": ex}\\n    if n_tasks:\\n        out[\\\"fixed_n\\\"] = {\\\"paired_tasks\\\": n_tasks,\\n                          \\\"delta_detectable\\\": delta_detectable(n_tasks, pd, alpha, power),\\n                          \\\"delta_excluded_95\\\": round(delta_excluded(n_tasks, pd), 4)}\\n    return out\\n\\nif __name__ == \\\"__main__\\\":\\n    ap = argparse.ArgumentParser()\\n    ap.add_argument(\\\"--pi\\\", type=float, required=True)\\n    ap.add_argument(\\\"--pd\\\", type=float, default=None)\\n    ap.add_argument(\\\"--alpha\\\", type=float, default=0.05)\\n    ap.add_argument(\\\"--power\\\", type=float, default=0.80)\\n    ap.add_argument(\\\"--n\\\", type=int, default=None)\\n    a = ap.parse_args()\\n    pd = a.pd if a.pd is not None else min(0.5, max(0.06, 0.9 * a.pi * (1 - a.pi)))\\n    print(json.dumps(report(a.pi, pd, a.alpha, a.power, a.n), indent=2))\\nPY\\npython3 tools/power_mcnemar.py --pi 0.08 --pd 0.12 --n 700\"}", "origin": "completion"}, "llm_response_id": "chatcmpl-bc562bd6-9458-4330-9beb-5bf4c2e0bb2e", "security_risk": "UNKNOWN", "critic_result": null, "summary": "execute_check: {\"command\": \"cd /workspace/design && cat > tools/power_mcnemar.py <<'PY'\\n#!/usr/bin/env python3\\n\\\"\\\"\\\"Paired-design feasibility modeling (stdlib only) -- FEASIBILITY MODEL, NOT A RESULT.\\n\\nBaseline success (pi) and discordant-pair mass (pd = b + c) are UNKNOWN design\\nparameters in this sandbox, so they are CLI inputs, never hard-coded facts.\\n\\nReports:\\n  1. n_closed_form / n_exact  : paired task count for the primary contrast\\n  2. delta_detectable         : smallest |risk difference| detectable at fixed n\\n  3. delta_excluded_95        : smallest |risk difference| the design EXCLUDES at 95%\\n           