rm(b, c, alpha, power):\\n    pd, dlt = b + c, abs(b - c)\\n    if dlt <= 0: return None\\n    za, zb = zq(1 - alpha / 2), zq(power)\\n    return int(math.ceil((za * math.sqrt(pd) + zb * math.sqrt(max(pd - dlt * dlt, 0.0))) ** 2 / dlt ** 2))\\n\\ndef delta_detectable(n, pd, alpha, power):\\n    if pd <= 0: return None\\n    for i in range(1, 2001):\\n        dlt = i / 1000.0\\n        if dlt >= pd: return None\\n        b, c = (pd + dlt) / 2, (pd - dlt) / 2\\n        p = power_exact(n, b, c, alpha) if n <= EXACT_CAP else power_approx(n, b, c, alpha)\\n        if p >= power: return dlt\\n    return None\\n\\ndef delta_excluded(n, pd):\\n    return 1.959964 * math.sqrt(max(pd, 1e-12) / n)\\n\\ndef report(pi, pd, alpha=0.05, power=0.80, n_tasks=None):\\n    out = {\\\"role\\\": \\\"feasibility_model_NOT_a_result\\\", \\\"assumed_pi\\\": pi, \\\"assumed_pd\\\": pd,\\n           \\\"alpha\\\": alpha, \\\"power\\\": power, \\\"power_method\\\": None, \\\"targets\\\": {}}\\n    for dlt in (0.02, 0.03, 0.05, 0.08):\\n        if dlt >= pd: continue\\n        b, c = (pd + dlt) / 2, (pd - dlt) / 2\\n        ncf = n_closed_form(b, c, alpha, power)\\n        ex = None\\n        if ncf and ncf <= EXACT_CAP:\\n            out[\\\"power_method\\\"] = \\\"exact conditional McNemar (n<=cap)\\\"\\n            ex = round(power_exact(ncf, b, c, alpha), 4)\\n        else:\\n            out[\\\"power_method\\\"] = \\\"exact for n<=cap else normal approximation\\\"\\n        out[\\\"targets\\\"][f\\\"rd_{dlt:.2f}\\\"] = {\\\"n_pairs_closed_form\\\": ncf,\\n                                          \\\"episodes_two_arms\\\": None if not ncf else 2 * ncf,\\n                                          \\\"exact_power_at_that_n\\\": ex}\\n    if n_tasks:\\n        out[\\\"fixed_n\\\"] = {\\\"paired_tasks\\\": n_tasks,\\n                          \\\"delta_detectable\\\": delta_detectable(n_tasks, pd, alpha, power),\\n                          \\\"delta_excluded_95\\\": round(delta_excluded(n_tas