 2, (pd - dlt) / 2, alpha) >= power: return dlt\\n    return None''',\\n'''def delta_detectable(n, pd, alpha, power):\\n    \\\"\\\"\\\"Invert the McNemar closed form for the smallest |risk difference| at power.\\\"\\\"\\\"\\n    if pd <= 0 or n <= 0: return None\\n    lo, hi = 1e-6, pd - 1e-6\\n    for _ in range(200):\\n        mid = (lo + hi) / 2\\n        need = (zq(1 - alpha / 2) * sqrt(pd) + zq(power) * sqrt(max(pd - mid * mid, 0.0))) ** 2 / mid ** 2\\n        if need > n: lo = mid\\n        else: hi = mid\\n    return hi''')\\np.write_text(s)\\nprint(\\\"patched\\\")\\nPY\\necho \\\"=== sanity: null calibration (b==c must give ~alpha) ===\\\"\\npython3 -c \\\"\\nimport sys; sys.path.insert(0,'tools')\\nfrom power_mcnemar import power_mcnemar, delta_detectable\\nfor n in (500,2000):\\n    print('n=',n,'b=c=0.06 -> power(=type-I)', round(power_mcnemar(n,0.06,0.06,0.05),4))\\nprint('power at rd=0.05,n=375,pd=0.12:', round(power_mcnemar(375,0.085,0.035,0.05),3))\\nprint('detectable at n=700,pd=0.12:', round(delta_detectable(700,0.12,0.05,0.8),4))\\n\\\"\", \"exit_code\": 0, \"timed_out\": false, \"elapsed_seconds\": 1.921, \"output\": \"patched\\n=== sanity: null calibration (b==c must give ~alpha) ===\\nn= 500 b=c=0.06 -> power(=type-I) 0.0374\\nn= 2000 b=c=0.06 -> power(=type-I) 0.0446\\npower at rd=0.05,n=375,pd=0.12: 0.774\\ndetectable at n=700,pd=0.12: 0.0366\\n\", \"output_truncated\": false}"}], "is_error": false, "kind": "BenchmarkObservation"}, "action_id": "92422a26-7e0e-46ad-8f85-318d6ce790c5", "extended_content": [], "kind": "ObservationEvent"}
