nd\": \"cd /workspace/design && for pi in 0.05 0.10 0.20; do echo \\\"### assumed baseline success pi=$pi (pd defaulted)\\\"; timeout 120 python3 tools/power_mcnemar.py --pi $pi --n 700 | python3 -c \\\"\\nimport json,sys\\nd=json.load(sys.stdin)\\nprint(' pd_assumed=',d['assumed_pd'])\\nfor k,v in d['targets'].items(): print('  ',k,'n_pairs=',v['n_pairs_closed_form'],'episodes=',v['episodes_two_arms'],'power_check=',v['power_check_at_that_n'])\\nprint('  fixed_n=700 ->',d['fixed_n'])\\n\\\"; done\"}", "kind": "ActionEvent"}
