 and y == 1) else 0\\n            pairs[(tid, st)] = (x, y)\\n    return b, c, n, pairs\\n\\ndef analyse(rows, alpha=0.05):\\n    rep = {\\\"primary\\\": {}, \\\"coprimary\\\": {}, \\\"secondaries_raw_p\\\": {}, \\\"secondaries_holm\\\": {},\\n           \\\"decision\\\": {}, \\\"diagnostics\\\": {}}\\n    b, c, n, pairs = pair_table(rows)\\n    suc = {\\\"cot\\\": sum(r[\\\"success\\\"] for r in rows if r[\\\"arm\\\"] == \\\"cot\\\"),\\n           \\\"nocot\\\": sum(r[\\\"success\\\"] for r in rows if r[\\\"arm\\\"] == \\\"nocot\\\")}\\n    cnt = {\\\"cot\\\": sum(1 for r in rows if r[\\\"arm\\\"] == \\\"cot\\\"),\\n           \\\"nocot\\\": sum(1 for r in rows if r[\\\"arm\\\"] == \\\"nocot\\\")}\\n    rd = (suc[\\\"cot\\\"]/cnt[\\\"cot\\\"] - suc[\\\"nocot\\\"]/cnt[\\\"nocot\\\"]) if min(cnt.values()) else float(\\\"nan\\\")\\n    lo, hi = cluster_bootstrap_rd(pairs) if pairs else (float(\\\"nan\\\"),)*2\\n    rep[\\\"primary\\\"] = {\\\"n_pairs\\\": n, \\\"b_cot_only\\\": b, \\\"c_nocot_only\\\": c,\\n                      \\\"success_rate\\\": {k: (suc[k]/cnt[k] if cnt[k] else None) for k in suc},\\n                      \\\"wilson95\\\": {k: list(wilson(suc[k], cnt[k])) for k in suc},\\n                      \\\"risk_difference\\\": rd, \\\"cluster_bootstrap95\\\": [lo, hi],\\n                      \\\"mcnemar_exact_p\\\": mcnemar_exact(b, c)}\\n\\n    # co-primary: equal expected output-token budget (no-CoT gets k samples if cheaper)\\n    def mean_tok(arm):\\n        v = [r[\\\"tok_out\\\"] for r in rows if r[\\\"arm\\\"] == arm]\\n        return sum(v)/len(v) if v else float(\\\"nan\\\")\\n    ta, tb = mean_tok(\\\"cot\\\"), mean_tok(\\\"nocot\\\")\\n    rep[\\\"coprimary\\\"] = {\\\"mean_tok_out\\\": {\\\"cot\\\": ta, \\\"nocot\\\": tb},\\n                        \\\"token_cost_ratio_cot_over_nocot\\\": (ta/tb) if tb else None,\\n                        \\\"success_per_1k_tokens\\\": {a: (suc[a]/cnt[a]/(mean_tok(a)/1000.0)\\n                                                      if cnt[a] and mean_tok(a) else None)\\n                                                  for a in suc},\\n                        \\\"note\\\": \\\"if CoT wins on success but not on success-per-token, the claim \\\"\\n                                \\\"must be 'more compute', not 'reasoning helps'\\\"}\\n\\n    # 2x2 CoT x k interaction (additive vs interaction) on paired tasks\\n    ks = sorted({r.get(\\\"k\\\", 1) for r in rows})\\n    eff = {}\\n    for k in ks:\\n        bb, cc, nn, _ = pair_table(rows, lambda r, k=k: r.get(\\\"k\\\", 1) == k)\\n        eff[f\\\"k={k}\\\"] = {\\\"b\\\": bb, \\\"c\\\": cc, \\\"n\\\": nn, \\\"p\\\": mcnemar_exact(bb, cc)}\\n    rep[\\\"secondaries_raw_p\\\"][\\\"cot_x_k\\\"] = eff\\n\\n    # strata / scaffold / temperature: paired contrasts per level\\n    for axis in (\\\"stratum\\\", \\\"scaffold\\\", \\\"temp\\\"):\\n        levels = sorted({str(r.get(axis)) for r in rows})\\n        out = {}\\n        for lv in levels:\\n            bb, cc, nn, _ = pair_table(rows, lambda r, lv=lv, ax=axis: str(r.get(ax)) == lv)\\n            out[lv] = {\\\"b\\\": bb, \\\"c\\\": cc, \\\"n\\\": nn, \\\"p\\\": mcnemar_exact(bb, cc)}\\n        rep[\\\"secondaries_raw_p\\\"][axis] = out\\n\\n    flat = {f\\\"{ax}:{lv}\\\": d[\\\"p\\\"] for ax, dd in rep[\\\"secondaries_raw_p\\\"].items()\\n            if isinstance(dd, dict) for lv, d in dd.items() if isinstance(d, dict) and \\\"p\\\" in d}\\n    rep[\\\"secondaries_holm\\\"] = holm(flat)\\n\\n    # decision rule\\n    p0 = rep[\\\"primary\\\"][\\\"mcnemar_exact_p\\\"]\\n    within = (not math.isnan(rd)) and abs(rd) + Z95*max(0.0,(hi-lo)/2/1.959963985) < RHO if not math.isnan(hi) else False\\n    rep[\\\"decision\\\"] = {\\n        \\\"rule\\\": \\\"improvement iff mcnemar_p<alpha AND bootstrap RD CI > 0 AND co-primary \\\"\\n                \\\"token-matched analysis does not attribute the gain to compute; \\\"\\n                \\\"equivalence iff CI lies entirely within +/-RHO; otherwise inconclusive\\\",\\n        \\\"alpha\\\": alpha, \\\"RHO\\\": RHO,\\n        \\\"observed_rd\\\": rd, \\\"ci_halfwidth\\\": None if math.isnan(hi) else (hi-lo)/2,\\n        \\\"ci_inside_equivalence_band\\\": within,\\n        \\\"smallest_excludable_effect\\\": None if not pairs else round(Z95*math.sqrt(max(b+c,1e-9)/max(len(pairs),1)), 4)}\\n    rep[\\\"diagnostics\\\"] = {\\\"parse_fail_rate\\\": {a: (sum(r[\\\"parse_fail\\\"] for r in rows if r[\\\"arm\\\"]==a)/cnt[a] if cnt[a] else None) for a in cnt},\\n                          \\\"mean_steps\\\": {a: (sum(r[\\\"steps\\\"] for r in rows if r[\\\"arm\\\"]==a)/cnt[a] if cnt[a] else None) for a in cnt},\\n                          \\\"mean_wall_s\\\": {a: (sum(r[\\\"wall_s\\\"] for r in rows if r[\\\"arm\\\"]==a)/cnt[a] if cnt[a] else None) for a in cnt}}\\n    return rep\\n\\n# ---------- synthetic self-test (validates code, not the hypothesis) ---------\\ndef selftest(n_tasks=400, seed=7, p0=0.20, delta=0.05):\\n    rng = random.Random(seed); rows = []\\n    for t in range(n_tasks):\\n        base = rng.betavariate(1, 4) * 0.6\\n        for arm, dl in ((\\\"cot\\\", delta), (\\\"nocot\\\", 0.0)):\\n            p = min(0.95, max(0.02, base + p0 * 0.3 + dl))\\n            ok = 1 if rng.random() < p else 0\\n            rows.append({\\\"task_id\\\": f\\\"T{t}\\\", \\\"arm\\\": arm, \\\"seed\\\": 0, \\\"success\\\": ok,\\n                         \\\"parse_fail\\\": 0, \\\"steps\\\": rng.randint(3, 20), \\\"wall_s\\\": rng.uniform(20, 300),\\n                         \\\"tok_out\\\": rng.randint(900, 2200) * (2 if arm == \\\"cot\\\" else 1),\\n                         \\\"stratum\\\": rng.choice([\\\"single_app\\\", \\\"cross_app\\\"]),\\n                         \\\"scaffold\\\": rng.choice([\\\"react\\\", \\\"plan_act\\\"]),\\n                         \\\"model\\\": \\\"M1\\\", \\\"temp\\\": rng.choice([0.0, 0.7]), \\\"k\\\": 1})\\n    rep = analyse(rows)\\n    return {\\\"NOTE\\\": \\\"SYNTHETIC code validation only - carries no evidence about WorkArena++\\\",\\n            \\\"planted_delta\\\": delta,\\n            \\\"recovered_rd\\\": round(rep[\\\"primary\\\"][\\\"risk_difference\\\"], 4),\\n            \\\"mcnemar_p\\\": rep[\\\"primary\\\"][\\\"mcnemar_exact_p\\\"],\\n            \\\"bootstrap_ci\\\": rep[\\\"primary\\\"][\\\"cluster_bootstrap95\\\"],\\n            \\\"code_checks\\\": {\\\"rd_sign_correct\\\": (rep[\\\"primary\\\"][\\\"risk_difference\\\"] > 0) == (delta > 0),\\n                            \\\"ci_brackets_point\\\": rep[\\\"primary\\\"][\\\"cluster_bootstrap95\\\"][0]\\n                            <= rep[\\\"primary\\\"][\\\"risk_difference\\\"] <= rep[\\\"primary\\\"][\\\"cluster_bootstrap95\\\"][1],\\n                            \\\"holm_monotone\\\": all(v >= 0 and v <= 1 for v in rep[\\\"secondaries_holm\\\"].values())}}\\n\\nif __name__ == \\\"__main__\\\":\\n    ap = argparse.ArgumentParser()\\n    ap.add_argument(\\\"--episodes\\\", help=\\\"JSONL of episode records\\\")\\n    ap.add_argument(\\\"--selftest\\\", action=\\\"store_true\\\")\\n    a = ap.parse_args()\\n    if a.selftest:\\n        print(json.dumps(selftest(), indent=2)); sys.exit(0)\\n    if not a.episodes: ap.error(\\\"--episodes FILE or --selftest\\\")\\n    print(json.dumps(analyse(load(a.episodes)), indent=2))\\nPY\\npython3 tools/analyze_skeleton.py --selftest\"}", "kind": "ActionEvent"}
