nrc, out, err = run([\"tools/leak_audit.py\", str(bad)])\nadd(\"leakage gate has teeth (flags a planted contaminated exemplar)\", rc == 1, out.strip().splitlines()[-1] if out else \"\")\n\nfrom statistics import NormalDist  # noqa: F401  (proves stdlib-only stats are enough)\nsys.path.insert(0, str(ROOT / \"tools\"))\nimport analyze_skeleton as A\nst = A.selftest()\nadd(\"analysis engine self-test (synthetic data, code validation only)\",\n    all(st[\"code_checks\"].values()), json.dumps(st[\"code_checks\"]))\n\nfrom math import comb\nok = True\nfor b, c in [(30, 10), (1, 0), (5, 5), (60, 40), (3, 1)]:\n    d, lo = b + c, min(b, c)\n    ref = min(1.0, 2 * sum(comb(d, i) * 0.5**d for i in range(lo + 1)))\n    ok &= abs(ref - A.mcnemar_exact(b, c)) < 1e-12\nadd(\"exact McNemar matches hand-computed binomial tails\", ok)\nh = A.holm({\"a\": 0.01, \"c\": 0.03, \"b\": 0.04})\nadd(\"Holm step-down matches hand computation (0.03/0.06/0.06)\", h == {\"a\": 0.03, \"c\": 0.06, \"b\": 0.06})\nw = A.wilson(8, 100)\nadd(\"Wilson interval matches hand computation for 8/100\", abs(w[0]-0.04109) < 1e-4 and abs(w[1]-0.14998) < 1e-4, str([round(x,5) for x in w]))\n\nimport power_mcnemar as P\nti = P.power_mcnemar(1000, 0.04, 0.04, 0.05)          # null: power must sit at/below alpha\nadd(\"McNemar power engine is calibrated at the null (<=alpha)\", ti <= 0.05, f\"type-I={ti:.4f}\")\npw = P.power_mcnemar(375, 0.085, 0.035, 0.05)\nadd(\"power engine reproduces target power for rd=0.05 at n=375 (0.70-0.90)\", 0.70 <= pw <= 0.90, f\"power={pw:.3f}\")\n\nrc, out, err = run([\"tools/budget_model.py\", \"--n-tasks\", \"700\", \"--reps\", \"3\"])\nj = json.loads(out)\nadd(\"budget model runs and tier1 is a subset of the total\", j[\"tier1_2_episodes\"] < j[\"total_episodes\"],\n    f\"total={j['total_episodes']} serial_days={j['wallclock_days_serial']}\")\n\ng = json.loads((ROOT / \"grid.json\").read_text())\ntiers = {c[\"id\"]: c[\"tier\"] for c in g[\"cells\"]}\nprune = [x.split(\" \")[0] for x in g[\"pruning_order_under_budget_pressure\"]]\nadd(\"tier-1 cells are never in the pruning order\", not (set(g[\"never_pruned\"]) & set(prune)),\n    f\"never_pruned={g['never_pruned']}\")\nadd(\"pruning order goes tier-3 -> tier-2 -> tier-1\", max(tiers[p] for p in prune[:4]) == 3 and all(tiers[p] >= 2 for p in prune))\n\nman = {str(p.relative_to(ROOT)): hashlib.sha256(p.read_bytes()).hexdigest()[:16]\n       for p in sorted(ROOT.rglob(\"*\")) if p.is_file() and \"__pycache__\" not in str(p) and p.name != \"MANIFEST.json\"}\n(ROOT / \"MANIFEST.json\").write_text(json.dumps(man, indent=2))\nadd(\"MANIFEST.json written (hashes of every shipped artifact)\", len(man) >= 10, f\"{len(man)} files\")\n\nprint(json.dumps({\"offline_checks\": results,\n                  \"n_pass\": sum(r[\"status\"] == \"PASS\" for r in results),\n                  \"n_fail\": sum(r[\"status\"] == \"FAIL\" for r in results),\n                  \"disclaimer\": \"No experiment executed; no WorkArena++ asset accessed; synthetic data used only to validate statistical code.\"},\n                 indent=2))\nsys.exit(1 if any(r[\"status\"] == \"FAIL\" for r in results) else 0)\nPY\npython3 tools/check_all.py; echo \"CHECK_ALL_EXIT=$?\"", "timeout_seconds": 60, "kind": "ExecuteCheckAction"}, "tool_name": "execute_check", "tool_call_id": "chatcmpl-tool-b7ff5eb7924c5885", "tool_call": {"id": "chatcmpl-tool-b7ff5eb7924c5885", "responses_item_id": null, "name": "execute_check", "arguments": "{\"command\": \"cd /workspace/design && cat > tools/check_all.py <<'PY'\\n#!/usr/bin/env python3\\n\\\"\\\"\\\"One-command self-check for the design package (stdlib only). Runs every offline\\nvalidator and prints PASS/FAIL. Validates artifacts and statistical code only;\\nit executes no experiment and touches no WorkArena++ asset.\\\"\\\"\\\"\\nimport json, pathlib, subprocess, sys, hashlib\\nROOT = pathlib.Path(__file__).resolve().parents[1]\\ndef run(cmd):\\n    p = subprocess.run([sys.executable] + cmd,